python3 - <<'PY'
from pathlib import Path
p = Path('/etc/nginx/nginx.conf')
txt = p.read_text()
to_add = []
if 'log_format benchmark' not in txt:
    to_add.append("    log_format benchmark '[$time_local] $request_method $status \"$http_user_agent\"';\n")
if 'limit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;' not in txt:
    to_add.append("    limit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;\n")
if to_add:
    marker = 'http {'
    i = txt.find(marker)
    if i == -1:
        raise SystemExit('http block not found in /etc/nginx/nginx.conf')
    i += len(marker)
    txt = txt[:i] + '\n' + ''.join(to_add) + txt[i:]
    p.write_text(txt)
PY
mkdir -p /var/www/html
printf 'Welcome to the benchmark webserver\n' > /var/www/html/index.html
printf 'Page not found - Please check your URL\n' > /var/www/html/404.html
cat >/etc/nginx/conf.d/benchmark-site.conf <<'EOF'
server {
    listen 8080;
    server_name localhost;

    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;

    limit_req zone=benchmark_limit burst=10;

    error_page 404 /404.html;
    location = /404.html { }

    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
rm -f /etc/nginx/sites-enabled/default
